            cp[i] = ('utf8', d[p:p+n].decode('utf-8','replace')); p += n
        elif tag == 3: cp[i] = ('int', struct.unpack('>i', d[p:p+4])[0]); p += 4
        elif tag == 4: cp[i] = ('float', struct.unpack('>f', d[p:p+4])[0]); p += 4
        elif tag == 5: cp[i] = ('long', struct.unpack('>q', d[p:p+8])[0]); p += 8; i += 1
        elif tag == 6: cp[i] = ('double', struct.unpack('>d', d[p:p+8])[0]); p += 8; i += 1
        elif tag in (7,8,16,19,20):
            cp[i] = ({7:'class',8:'string',16:'mt',19:'mod',20:'pkg'}[tag],
                     struct.unpack('>H', d[p:p+2])[0]); p += 2
        elif tag in (9,10,11,12,17,18):
            a,b = struct.unpack('>HH', d[p:p+4])
            cp[i] = ({9:'field',10:'meth',11:'imeth',12:'nat',17:'dyn',18:'indy'}[tag], (a,b)); p += 4
        elif tag == 15: cp[i] = ('mh', d[p:p+3]); p += 3
        elif tag == 25: cp[i] = ('pmt', d[p:p+2]); p += 2
        elif tag == 24:
            n = struct.unpack('>I', d[p:p+4])[0]; p += 4+n
        else: raise Exception('tag %d' % tag)
        i += 1
    return cp, p

def S(cp,k):
    v = cp.get(k)
    return v[1] if v and v[0]=='utf8' else '#%d'%k
def R(cp,k):
    v = cp.get(k)
    if not v: return '#%d'%k
