1071	    const gl = this.gl;
1072	    const { rx, ry, rz, ux, uy, uz } = basisFromYawPitch(this.yaw, this.pitch);
1073	    const time = ((worldTicks % 24000) + 24000) % 24000;
1074	    const angle = (time / 24000) * Math.PI * 2;
1075	    const sun = [Math.cos(angle), Math.sin(angle), 0.18];
1076	    const sl = Math.hypot(...sun);
1077	    sun[0] /= sl; sun[1] /= sl; sun[2] /= sl;
1078	    const moon = [-sun[0], -sun[1], -sun[2]];
1079	    const eye = this.eye;
1080	    const build = (dir: number[], size: number): Float32Array => {
1081	      const c = [eye[0] + dir[0] * 100, eye[1] + dir[1] * 100, eye[2] + dir[2] * 100];
1082	      const h = size / 2;
1083	      const p = [
1084	        c[0] - rx * h - ux * h, c[1] - ry * h - uy * h, c[2] - rz * h - uz * h,
1085	        c[0] + rx * h - ux * h, c[1] + ry * h - uy * h, c[2] + rz * h - uz * h,
1086	        c[0] + rx * h + ux * h, c[1] + ry * h + uy * h, c[2] + rz * h + uz * h,
1087	        c[0] - rx * h + ux * h, c[1] - ry * h + uy * h, c[2] - rz * h + uz * h,
1088	      ];
1089	      const uv = [0, 1, 1, 1, 1, 0, 0, 0];
1090	      const out: number[] = [];
1091	      for (const i of [0, 1, 2, 0, 2, 3]) out.push(p[i * 3], p[i * 3 + 1], p[i * 3 + 2], uv[i * 2], uv[i * 2 + 1]);
1092	      return new Float32Array(out);
1093	    };
1094	    gl.enable(gl.BLEND);
1095	    gl.blendFunc(gl.SRC_ALPHA, gl.ONE);
1096	    gl.depthMask(false);
1097	    gl.disable(gl.DEPTH_TEST);
1098	    this.celestialProgram.use();
1099	    this.celestialProgram.mat4('uViewProj', this.vp);
1100	    gl.bindVertexArray(this.celestialVao);
1101	    if (sun[1] > -0.12) {
1102	      gl.bindBuffer(gl.ARRAY_BUFFER, this.celestialVbo);
1103	      gl.bufferData(gl.ARRAY_BUFFER, build(sun, 18), gl.DYNAMIC_DRAW);
1104	      gl.activeTexture(gl.TEXTURE0);
1105	      gl.bindTexture(gl.TEXTURE_2D, this.sunTex);
1106	      this.celestialProgram.i('uTex', 0);
1107	      this.celestialProgram.v4('uColor', 1, 1, 1, clamp((sun[1] + 0.12) * 4, 0, 1));
