1109	    }
1110	    if (moon[1] > -0.12) {
1111	      gl.bindBuffer(gl.ARRAY_BUFFER, this.celestialVbo);
1112	      gl.bufferData(gl.ARRAY_BUFFER, build(moon, 6), gl.DYNAMIC_DRAW);
1113	      gl.activeTexture(gl.TEXTURE0);
1114	      gl.bindTexture(gl.TEXTURE_2D, this.moonTex);
1115	      this.celestialProgram.i('uTex', 0);
1116	      this.celestialProgram.v4('uColor', 1, 1, 1, clamp((moon[1] + 0.12) * 4, 0, 1));
1117	      gl.drawArrays(gl.TRIANGLES, 0, 6);
1118	    }
1119	    gl.disable(gl.BLEND);
1120	    gl.depthMask(true);
1121	    gl.enable(gl.DEPTH_TEST);
